from bisect import bisect_right


def doubledMedianOfThree(a, b, c):
    n = len(a) + len(b) + len(c)

    def kth(k):
        lo, hi = -10 ** 9, 10 ** 9
        while lo < hi:
            mid = (lo + hi) // 2
            if bisect_right(a, mid) + bisect_right(b, mid) + bisect_right(c, mid) >= k + 1:
                hi = mid
            else:
                lo = mid + 1
        return lo

    return kth((n - 1) // 2) + kth(n // 2)
